    public async Task<bool> ConnectAsync()
    {
        var uri = new Uri($"{(ClientInfo.UseSSL?"wss":"ws")}://{ClientInfo.Server}/showdown/websocket");
        await _webSocket.ConnectAsync(uri, CancellationToken.None);
        _recvThread = new Thread(async () => await RecvAsync());
        _recvThread.Start();
        return _webSocket.State == WebSocketState.Open;
    }
    private async Task RecvAsync()
    {
        var buffer = new byte[1024 * 32]; // 32KB buffer
        while (_webSocket.State == WebSocketState.Open
        && !_disposed
        )
        {
            try
            {
                // Generated by Copilot - 使用Serilog记录接收线程状态
                Logger.Information("Receiving messages from WebSocket...");
                var result = await _webSocket.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
                if (result.MessageType == WebSocketMessageType.Close)
                {
                    await _webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Closing", CancellationToken.None);
                }
                else if (result.MessageType == WebSocketMessageType.Text)
                {
                    var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                    // Generated by Copilot - 使用Serilog记录接收到的消息
                    WriteLogAsync(message, MsgType.Receive);
                    await ExcuteMessageAsync(message);
                }
                else
                {
                    Logger.Warning("Received unsupported message type: {MessageType}", result.MessageType);
                }
            }
            catch (Exception ex)
            {
                Logger.Error(ex, "Error in receiving thread");
                break;
            }

        }
    }
    public async Task<bool> LoginAsync(string userName, string challId, string chall)
    {

        var content = new FormUrlEncodedContent(
      [
              new KeyValuePair<string, string>("act", "getassertion"),
                new KeyValuePair<string, string>("userid", userName),
                new KeyValuePair<string, string>("challstr", $"{challId}%7C{chall}")
          ]);
        var response = await _httpClient.PostAsync(ClientInfo.AuthSUrl, content);

        var dd = await response.Content.ReadAsStringAsync();

        await SendAsync("", $"/trn {userName},0,{dd}");
        await SetAvatarAsync("lillie");
        return true;
    }


    public async Task<bool> LoginAsync(string userName, string password, string challId, string chall)
    {

        var content = new FormUrlEncodedContent(
            [
                    new KeyValuePair<string, string>("act", "login"),
                new KeyValuePair<string, string>("name", userName),
                new KeyValuePair<string, string>("pass", password),
                new KeyValuePair<string, string>("challstr", $"{challId}%7C{chall}")
                ]);

        // 发送登录请求
        var response = await _httpClient.PostAsync(ClientInfo.AuthSUrl, content);
        var responseString = await response.Content.ReadAsStringAsync();
        var json = responseString[1..]; // 跳过第一个字符
        var data = JsonDocument.Parse(json).RootElement;

        if (!data.GetProperty("curuser").GetProperty("loggedin").GetBoolean())
            return false;

        var assertion = data.GetProperty("assertion").GetString();
        await SendAsync("", $"/trn {userName},0,{assertion}");
        await SetAvatarAsync("lillie");
        return true;
    }

