    public void Disconnect()
    {
        if (_webSocket != null && _webSocket.State == WebSocketState.Open)
        {
            _webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Client disconnected", CancellationToken.None).Wait();
        }
        _disposed = true;
        _recvThread?.Join();
        _recvThread = null;
        _webSocket?.Dispose();
        _webSocket = null;
        Logger.Information("Disconnected from WebSocket");
    }

    // Generated by Copilot - 使用Serilog记录日志
    private void WriteLogAsync(string msg, MsgType type)
    {
        switch (type)
        {
            case MsgType.Receive:
                Logger.Information("Received: {Message}", msg);
                break;
            case MsgType.Send:
                Logger.Information("Sent: {Message}", msg);
                break;
            default:
                Logger.Warning("Unknown message type: {MessageType}, Message: {Message}", type, msg);
                break;
        }
    }


    private async Task BattleTagAsync(string msg, Usage usage = Usage.Standby)
    {
        string[] battleData = msg.Split('\n');
        string tag = battleData[0].Split('|')[0][1..];
        // Console.WriteLine($"tag: {tag}");
        var battle = Battles.GetValueOrDefault(tag) ?? new PSBattle(this, tag);
        BattleInfo?.Invoke(battle, msg);

        for (int i = 1; i < battleData.Length; i++)
        {
            string[] currData = battleData[i].Split('|');
            if (currData.Length < 2) continue;
            string cmd = currData[1];
            string[] other = currData[2..];

            //Console.WriteLine(cmd);
            //Console.WriteLine(battle.BattleData.GetMyTeam());
            battle.BattleData = (await battle.BattleData.ApplyLog(cmd, other)).AddTurnLog(battleData[i]);
            //Console.WriteLine(cmd);
            //Console.WriteLine(battle.BattleData.GetMyTeam());
            switch (cmd)
            {
                case "init":
                    Battles.TryAdd(tag, battle);
                    OnBattleStart?.Invoke(battle);
                    break;
                case "player":
                    // Todo: 这个也要高的battledata里
                    if (other[1] == ClientInfo.Name)
                    {
                        battle.PlayerPosition = other[0] == "p1" ? PlayerPosition.Player1 : PlayerPosition.Player2;
                        // Console.WriteLine("玩家位置: " + battle.PlayerPos);
                        if (battle.PlayerPosition == PlayerPosition.Player1)
                        {
                            battle.Player1 = ClientInfo.Name;
                        }
                        else
                        {
                            // battle.Turn++;
                            battle.Player2 = ClientInfo.Name;
                        }
                    }
                    else
                    {
                        if (other[0] == "p1")
                        {
                            battle.Player1 = other[1];
                        }
                        else
                        {
                            battle.Player2 = other[1];
                        }
                    }
                    break;
                case "request":
                    if (other[0] != "")
                    {
                        RequestsAction?.Invoke(battle);

                        // battle.Turn += 2;

                        //if (JsonDocument.Parse(other[0]).RootElement.TryGetProperty("forceSwitch", out var c))
                        //{
                        //    await SendSwitchAsync(tag, ++battle.idx, battle.Turn);
                        //}
                        // 随机队伍信息
                        // 应该还需要拆分
                        if (other[0].Length == 1)
                        {
                            await battle.RefreshByRequestAsync(other[1].Split('\n')[1]);
                            // RequestsAction?.Invoke(tag, other[1].Split('\n')[1]);
                            // other[1].split('\n')[1] 为队伍信息
                        }
                        else
                        {
                            await battle.RefreshByRequestAsync(other[0]);
                            // RequestsAction?.Invoke(tag, other[0]);

                            // other[0] 为队伍信息
                        }
                    }

                    break;
                case "teampreview":
                    // 后面还有个
                    OnSetTeam?.Invoke(battle);

                    //OnTeampreview?.Invoke(battle);
                    // 选择队伍
                    // 可能需要事件通知
                    // MakeOrder
                    break;
                case "turn":
                    // 回合开始
                    // 做出操作
                    // MakeAction
                    // Console.WriteLine("到了turn");
                    //OnChooseMove?.Invoke(battle);
                    // await SendMoveAsync(tag, 1, battle.Turn);
                    battle.NextTurn();
                    break;
                case "callback":
                    if (other[0] == "trapped")
                    {
                        // makemove
                        // 招式失败 好像
                    }
                    break;
                case "poke":
                    if (other[0] == (battle.PlayerPosition == PlayerPosition.Player1 ? "p2" : "p1"))
                    {
                        // 对手的队伍信息
                        var data = other[1].Split(", ");
                        // 0 名字 1 等级
                        await battle.InitOppTeamAsync(data[0]);
                        //battle.OppTeam;
                        // Console.WriteLine(other[1]);
                        //// Console.WriteLine("让我康康");
                    }
                    break;
                case "win":
                    // Console.WriteLine("对战结束");
                    OnBattleEnd?.Invoke(battle, other[0].Contains(ClientInfo.Name));
                    Battles.Remove(battle.Tag);
                    // 对战结束
                    break;
                case "error":
                    OnBattleError?.Invoke(battle, other[0]);
                    // 出现异常
                    break;
                default:
                    battle.LogParse(cmd, other);
                    break;
            }
        }
    }



    private async Task ExcuteMessageAsync(string message, Usage usage = Usage.Standby)
    {
        // Console.WriteLine(message);
        //Debug.WriteLine(message);
        var data = message.Split('|');
        // Console.WriteLine(data[0]);


        if (data[0].Contains("battle"))
        {
            // 对战数据
            // Console.WriteLine("这里是对战...");
            await BattleTagAsync(message, usage);
        }
        else
        {
            switch (data[1])
            {
                case "challstr":
                    //_challId = data[2];
                    //_chall = data[3];

                    ChallInfo = ChallInfo.Create(data[2], data[3]);
                    // 允许登录
                    break;
                case "updateuser":
                    UpdateUser?.Invoke();
                    // 用户更新 可认为登陆完毕（？
                    break;
                case "updatesearch":
                    // 更新房间，json
                    // {"searching":[],"games":{"battle-gen8randombattle-1605790743":"[Gen 8] Random Battle"}}
                    break;
                case "deinit":
                    // 对战结束
                    break;
                case "init":

                    OnBattleRuleInit?.Invoke(message);

                    break;
                case "queryresponse":
                    switch (data[2])
                    {
                        case "roomlist":
                            // 想办法传回去

                            OnGetRoomList?.Invoke(JsonSerializer.Deserialize<Roomlist>(data[3]));

                            break;
                        case "userdetails":
                            OnUserDetails?.Invoke(data[3]);
                            break;
                        default:
                            break;
                    }

                    break;
                case "updatechallenges":
                    if (data[2].Split("\"")[3] != "challengeTo")
                    {
                    }

                    break;
                case "pm":
                    string pmP1 = data[2].Trim(), pmP2 = data[3].Trim();
                    if (data[4].StartsWith('/'))
                    {
                        string[] cmd = data[4].Split(' ');
                        // foreach (var cmdd in cmd)
                        // {
                        //     // Console.WriteLine(cmdd);
                        // }
                        switch (cmd[0])
                        {
                            case "/challenge":
                                if (cmd.Length == 1)
                                {
                                    WriteLogAsync($"{pmP2}取消挑战", MsgType.Receive);
                                    break;
                                }

                                string rule = cmd[1];
                                string rule2 = data[5];
                                // // Console.WriteLine($"rule2: {rule}");
                                if (pmP1 == ClientInfo.Name)
                                {
                                    WriteLogAsync($"发起对{pmP2}挑战, 规则：{rule}", MsgType.Receive);
                                }
                                else
                                {
                                    WriteLogAsync($"收到{pmP1}挑战, 规则：{rule}", MsgType.Receive);
                                    // 触发挑战事件
                                    OnChallenge?.Invoke(pmP1, rule);
                                }

                                break;
                            case "/log":
                                break;
                            default:
                                break;
                        }
                    }
                    else
                    {
                        // 聊天信息
                        WriteLogAsync($"[聊天信息] {pmP1} -> {pmP2}: {data[4]}", MsgType.Receive);
                        if (pmP2 == ClientInfo.Name)
                        {
                            OnChat?.Invoke(pmP1, data[4]);
                        }
                    }

                    if (data[2].Trim() == ClientInfo.Name)
                    {
                        // 我发起的挑战
                    }

                    break;

                default:
                    break;
            }
        }
        // if (data[0].Contains("battle"))
        // {
        //     // 为对战数据
        // }
    }


